{"disposition":"candidate","reason":"Re-derived all src/tiles.mjs replacements with contextual before strings so each matches once in sequential application; both pageHref(cell.name) occurrences are uniquely identified.","edits":[{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"function pageHref(name) {
  return `/${name}/`;
}","after":"function pageHref(name, homeName) {
  return name === homeName ? '/' : `/${name}/`;
}","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"function cellTile(cell, { relation, direction, current = false } = {}) {","after":"function cellTile(cell, { relation, direction, current = false, homeName } = {}) {","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"html: `${summary}<p><a href="${escapeHtml(pageHref(cell.name))}">Open page</a></p>`,","after":"html: `${summary}<p><a href="${escapeHtml(pageHref(cell.name, homeName))}">Open page</a></p>`,","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"export function renderAtlasPage(cellsSorted, { site, discovery }) {","after":"export function renderAtlasPage(cellsSorted, { site, discovery, homeName }) {","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"tiles: cellsSorted.map((cell) => cellTile(cell)),","after":"tiles: cellsSorted.map((cell) => cellTile(cell, { homeName })),","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"export function renderNeighborhoodPage(cell, { site, cells, incoming, discovery }) {","after":"export function renderNeighborhoodPage(cell, { site, cells, incoming, discovery, homeName }) {","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"related.push(cellTile(cells.get(name), { relation: relation.type, direction: 'outgoing' }));","after":"related.push(cellTile(cells.get(name), { relation: relation.type, direction: 'outgoing', homeName }));","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"related.push(cellTile(cells.get(relation.from), { relation: relation.type, direction: 'incoming' }));","after":"related.push(cellTile(cells.get(relation.from), { relation: relation.type, direction: 'incoming', homeName }));","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"tiles: [cellTile(cell, { current: true }), ...related],","after":"tiles: [cellTile(cell, { current: true, homeName }), ...related],","clauses":["F-H05"]},{"path":"src/tiles.mjs","inputSha256":"7c18b229db8e5a38c982fc71f2a43c781dfb93fd8b93c8ccb9ec15b242dda61a","before":"footerHtml: `<nav aria-label="Return"><a href="${escapeHtml(pageHref(cell.name))}">Return to ${escapeHtml(cell.title)}</a> · <a href="/atlas/">Open atlas</a></nav>`,","after":"footerHtml: `<nav aria-label="Return"><a href="${escapeHtml(pageHref(cell.name, homeName))}">Return to ${escapeHtml(cell.title)}</a> · <a href="/atlas/">Open atlas</a></nav>`,","clauses":["F-H05"]}]}
